independent.solution:
events = [
    (1, 'a', '10', 'paid', '2025-05-01', 1),
    (2, 'b', 'x', 'paid', '2025-05-01', 1),
    (3, '', '5', 'paid', '2025-05-01', 1),
    (4, 'c', '20', 'paid', '2025-05-02', 1),
    (4, 'c', '20', 'refunded', '2025-05-02', 2),
    (5, 'd', '-3', 'paid', '2025-05-02', 1),
    (6, 'e', '30', 'paid', '2025-05-02', 1),
]
valid, rejected = [], 0
for oid, cust, amt, status, date, ts in events:
    try:
        value = float(amt)
    except ValueError:
        rejected += 1
        continue
    if value < 0 or cust == '':
        rejected += 1
        continue
    valid.append((oid, value, status, date, ts))
latest = {}
for oid, value, status, date, ts in valid:
    if oid not in latest or ts > latest[oid][3]:
        latest[oid] = (value, status, date, ts)
duplicates = len(valid) - len(latest)
print('read:', len(events), 'rejected:', rejected, 'duplicates:', duplicates, 'loaded:', len(latest))
daily = {}
for value, status, date, ts in latest.values():
    if status == 'paid':
        daily[date] = daily.get(date, 0.0) + value
for d in sorted(daily):
    print(d + ':', round(daily[d], 1))
print('reconciles:', len(events) == len(latest) + rejected + duplicates)
